from django.db import migrations, models


# Exact-match answers from the retired 11-question form are copied onto the
# sheet item they answered, so a pending application keeps its pre-fill. Only
# exact matches are copied: the old pregnancy/breastfeeding, recent-illness and
# vaccination statements were broader or narrower than their nearest item.
def copy_legacy_answers(apps, schema_editor):
    Interview = apps.get_model("accounts", "RegistrationInterview")
    for row in Interview.objects.all():
        values = {
            "q01": row.felt_well_today,
            "q02": row.previously_deferred,
            "q12": row.prior_transfusion,
            "q13": row.dental_procedure,
            "q14": row.tattoo_piercing,
            "q15": row.high_risk_behavior,
            "q23": row.reactive_test,
        }
        meds = (row.on_medication, row.recent_vaccination)
        if any(value is True for value in meds):
            values["q07"] = True
        elif all(value is False for value in meds):
            values["q07"] = False
        changed = [name for name, value in values.items() if value is not None]
        if not changed:
            continue
        for name in changed:
            setattr(row, name, values[name])
        row.save(update_fields=changed)


